recipes.code:
{
  "inputs": [
    {
      "id": "demipass-token",
      "type": "promptString",
      "description": "Dustforge JWT bearer token. Self-onboard at https://dustforge.com/.well-known/silicon or mint via the 2FA email flow.",
      "password": true
    }
  ],
  "servers": {
    "demipass": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "demipass@2.5.0"
      ],
      "env": {
        "DEMIPASS_TOKEN": "${input:demipass-token}",
        "DEMIPASS_URL": "<demipass-url>"
      }
    }
  }
}
